void report_progress(const PortExportOptions& options, const std::string_view phase) {
    if (!options.progress_callback) return;
    try {
        options.progress_callback(phase);
    } catch (...) {
        options.progress.record_observation_loss();
    }
}

void report_deferred_latent_primary_root_seed_cache_failure(
    const std::string_view stage,
    const std::string_view reason) noexcept {
    const auto write_token = [](const std::string_view token) noexcept {
        constexpr std::size_t maximum_token_bytes = 48u;
        const auto count = std::min(token.size(), maximum_token_bytes);
        for (std::size_t index = 0u; index < count; ++index) {
            const auto character =
                static_cast<unsigned char>(token[index]);
            const bool ascii_alphanumeric =
                (character >= static_cast<unsigned char>('a') &&
                 character <= static_cast<unsigned char>('z')) ||
                (character >= static_cast<unsigned char>('A') &&
                 character <= static_cast<unsigned char>('Z')) ||
                (character >= static_cast<unsigned char>('0') &&
                 character <= static_cast<unsigned char>('9'));
            const char output =
                ascii_alphanumeric || character == '-' || character == '_'
                    ? static_cast<char>(character)
                    : '_';
            static_cast<void>(std::fputc(output, stderr));
        }
    };
    static_cast<void>(std::fputs(
        "KATANA_ANALYZE_PORT_ROOT_SEED_CACHE_PUBLISH_DIAGNOSTIC "
        "stage=",
        stderr));
    write_token(stage);
    static_cast<void>(std::fputs(" reason=", stderr));
    write_token(reason);
    static_cast<void>(std::fputc('\n', stderr));
    static_cast<void>(std::fflush(stderr));
}

void report_native_disc_analysis_artifact_failure(
    const std::string_view stage,
    const std::string_view reason) noexcept {
    const auto write_token = [](const std::string_view token) noexcept {
        constexpr std::size_t maximum_token_bytes = 96u;
        const auto count = std::min(token.size(), maximum_token_bytes);
        for (std::size_t index = 0u; index < count; ++index) {
            const auto character =
                static_cast<unsigned char>(token[index]);
            const bool ascii_alphanumeric =
                (character >= static_cast<unsigned char>('a') &&
                 character <= static_cast<unsigned char>('z')) ||
                (character >= static_cast<unsigned char>('A') &&
                 character <= static_cast<unsigned char>('Z')) ||
                (character >= static_cast<unsigned char>('0') &&
                 character <= static_cast<unsigned char>('9'));
            const char output =
                ascii_alphanumeric || character == '-' || character == '_'
                    ? static_cast<char>(character)
                    : '_';
            static_cast<void>(std::fputc(output, stderr));
        }
    };
    static_cast<void>(std::fputs(
        "KATANA_NATIVE_DISC_ANALYSIS_ARTIFACT_DIAGNOSTIC stage=",
        stderr));
    write_token(stage);
    static_cast<void>(std::fputs(" reason=", stderr));
    write_token(reason);
    static_cast<void>(std::fputc('\n', stderr));
    static_cast<void>(std::fflush(stderr));
}

bool valid_target_name(const std::string_view value) noexcept {
    if (value.empty() || !std::isalpha(static_cast<unsigned char>(value.front()))) {
        return false;
    }
    const bool valid = std::all_of(value.begin(), value.end(), [](const unsigned char character) {
        return std::isalnum(character) || character == '_' || character == '-';
    });
    return valid && value != "katana-recomp" && value != "katana_runtime" &&
           value != "katana_core" && value != "katana_generated" && value != "all" &&
           value != "clean" && value != "install" && value != "test" && value != "help" &&
           value != "rebuild_cache";
}

