    64u * 1024u * 1024u;
// Full product source maps can exceed the per-partition ceiling by a wide
// margin.  They are deterministic metadata products and already pass through
// the integrity-bound cache API, so retain a separate finite ceiling instead
// of forcing every incremental export to rebuild them from millions of
// address/source records.
constexpr std::size_t maximum_port_metadata_cache_artifact_bytes =
    512u * 1024u * 1024u;

bool unsafe_port_path_link(
    const std::filesystem::path& path,
    const std::filesystem::file_status status) noexcept {
    if (std::filesystem::is_symlink(status)) return true;
#ifdef _WIN32
    try {
        auto inspected = std::filesystem::absolute(path).lexically_normal();
        inspected.make_preferred();
        const auto native = inspected.native();
        if (native.starts_with(LR"(\\.\)")) return true;
        if (!native.starts_with(LR"(\\?\)")) {
            inspected = native.starts_with(LR"(\\)")
                ? std::filesystem::path(
                      std::wstring(LR"(\\?\UNC\)") + native.substr(2u))
                : std::filesystem::path(
                      std::wstring(LR"(\\?\)") + native);
        }
        const auto attributes = GetFileAttributesW(inspected.c_str());
        return attributes == INVALID_FILE_ATTRIBUTES ||
               (attributes & FILE_ATTRIBUTE_REPARSE_POINT) != 0u;
    } catch (...) {
        return true;
    }
#else
    static_cast<void>(path);
    return false;
#endif
}

void ensure_safe_port_directory(
    const std::filesystem::path& root,
    const std::filesystem::path& relative) {
    auto current = root;
    for (const auto& component : relative) {
        if (component.empty() || component == ".") continue;
        if (component == "..")
            throw std::runtime_error(
                "Portverzeichnis verlaesst sein Ausgabeziel.");
        current /= component;
        std::error_code status_error;
        auto status =
            std::filesystem::symlink_status(current, status_error);
        if (status_error == std::errc::no_such_file_or_directory ||
            (!status_error &&
             status.type() ==
                 std::filesystem::file_type::not_found)) {
            status_error.clear();
            if (!std::filesystem::create_directory(
                    current, status_error) &&
                status_error)
                throw std::filesystem::filesystem_error(
                    "Portverzeichnis konnte nicht erstellt werden.",
                    current,
                    status_error);
            status =
                std::filesystem::symlink_status(current, status_error);
        }
        if (status_error ||
            !std::filesystem::is_directory(status) ||
            unsafe_port_path_link(current, status))
            throw std::runtime_error(
                "Portverzeichnis ist kein sicherer regulaerer Ordner.");
    }
}

std::string_view console_profile_enumerator(const std::string_view profile) {
    if (profile == "japan-ntsc") return "JapanNtsc";
    if (profile == "north-america-ntsc") return "NorthAmericaNtsc";
    if (profile == "europe-pal") return "EuropePal";
    if (profile == "vga") return "Vga";
    throw std::invalid_argument("Unbekanntes Dreamcast-Konsolenprofil.");
}

