            std::any_of(
                native_templates.begin(),
                native_templates.end(),
                [&](const auto& candidate) {
                    return candidate.source_start == entry.guest_address;
                }) ||
            std::any_of(
                external_native_templates.begin(),
                external_native_templates.end(),
                [&](const auto& candidate) {
                    return candidate.source_start == entry.guest_address;
                });
